func TestTextChrome(t *testing.T) {
	chrome := readChromeText(t, "chrome.json")
	docs, _ := filepath.Glob(filepath.Join("..", "..", "testdata", "text", "docs", "*.html"))
	if len(docs) < 10 {
		t.Fatalf("only %d text documents", len(docs))
	}
	nBoxes, nLines := 0, 0
	for _, path := range docs {
		name := strings.TrimSuffix(filepath.Base(path), ".html")
		t.Run(name, func(t *testing.T) {
			src, _ := os.ReadFile(path)
			b, l := compareText(t, name, src, chrome)
			nBoxes, nLines = nBoxes+b, nLines+l
		})
	}
	t.Logf("compared %d boxes and %d lines", nBoxes, nLines)
}

// compareText checks one document against Chromium's data and returns the
// number of boxes and lines compared.
func compareText(t *testing.T, name string, src []byte, chrome map[string]chromeText) (nBoxes, nLines int) {
	want, ok := chrome[name]
	if !ok {
		t.Fatalf("no Chromium data; run `make crosscheck`")
	}
	known, isKnown := knownTextDiffs[name]
	errs, nBoxes, nLines, warns := diffText(src, want, known.tol)
	if len(warns) > 0 {
		t.Errorf("warnings: %q", warns)
	}
	if isKnown {
		t.Logf("tolerance %v (%s)", known.tol, known.why)
		// Self-check: a listed case must still need its tolerance.
		if exact, _, _, _ := diffText(src, want, 0); len(errs) == 0 && len(exact) == 0 {
			t.Errorf("now matches Chromium exactly; remove it from knownTextDiffs")
		}
	}
	if len(errs) > 0 {
		if known.skip {
			t.Logf("accepted: %d differences", len(errs))
			return
		}
		t.Errorf("%d differences:\n%s", len(errs), strings.Join(errs, "\n"))
	}
	return
}

// diffText lays out src and lists its differences from Chromium's data,
// allowing tol (1/64 px) per coordinate.
func diffText(src []byte, want chromeText, tol geom.Unit) (errs []string, nBoxes, nLines int, warns []string) {
	m := sizeRE.FindSubmatch(src)
	var w, h int
	fmt.Sscan(string(m[1]), &w)
	fmt.Sscan(string(m[2]), &h)
	d := Build(string(src), "")
	d.Layout(w, h)
	var boxes []*Box
	var all func(b *Box)
	all = func(b *Box) {
		boxes = append(boxes, b)
		for _, ib := range b.inlines {
			if ib.El.Tag() != "br" {
				boxes = append(boxes, ib)
			}
		}
		for _, k := range b.Kids {
			all(k)
		}
	}
	all(d.Root)
	if len(boxes) != len(want.Boxes) {
		return []string{fmt.Sprintf("%d boxes, Chromium has %d", len(boxes), len(want.Boxes))}, 0, 0, d.Warnings
	}
	nearR := func(a, b [4]geom.Unit) bool {
		return near(a[0], b[0], tol) && near(a[1], b[1], tol) && near(a[2], b[2], tol) && near(a[3], b[3], tol)
	}
	ti := 0
	for i, bx := range boxes {
		wb := want.Boxes[i]
		got := [4]geom.Unit{bx.Abs.X, bx.Abs.Y, bx.Abs.W, bx.Abs.H}
		exp := [4]geom.Unit{toUnit(wb[0]), toUnit(wb[1]), toUnit(wb[2]), toUnit(wb[3])}
		nBoxes++
		if !nearR(got, exp) {
			errs = append(errs, fmt.Sprintf("box %d (%s): got %v want %v", i, label(bx), fmtR(got), fmtR(exp)))
		}
		if bx.Text == nil {
			continue
		}
		wl := want.Lines[ti]
		ti++
		tx := bx.Text
		// Lines without characters (from <br><br>) are invisible to the
		// Chromium script; box heights cover them.
		var lines []text.Line
		for _, ln := range tx.Layout(bx.Abs.W).Lines {
			if ln.FullEnd > ln.Start {
				lines = append(lines, ln)
			}
		}
		if len(lines) != len(wl) {
			errs = append(errs, fmt.Sprintf("box %d %q: %d lines, Chromium %d", i, tx.String(), len(lines), len(wl)))
			continue
		}
		for k, ln := range lines {
			nLines++
			if ln.Ellipsis {
				continue // Chromium reports the untruncated characters
			}
			str := tx.Runes(ln.Start, ln.End)
			if tx.Params().WhiteSpace != style.WhiteSpacePre {
				str = strings.TrimRight(str, " ")
			}
			top, bot := tx.LineInk(&ln)
			ix0, ix1 := tx.Ink(&ln)
			g := [4]geom.Unit{bx.Abs.X + ix0, bx.Abs.Y + top, ix1 - ix0, bot - top}
			c := wl[k]
			e := [4]geom.Unit{toUnit(c[1].(float64)), toUnit(c[2].(float64)), toUnit(c[3].(float64)), toUnit(c[4].(float64))}
			if str != c[0] || !nearR(g, e) {
				errs = append(errs, fmt.Sprintf("box %d line %d:\n   got  %q %s\n   want %q %s", i, k, str, fmtR(g), c[0], fmtR(e)))
			}
			if len(c) > 5 && str == c[0] {
				errs = append(errs, diffChars(tx, &ln, bx.Abs.X, c[5].([]any), tol, fmt.Sprintf("box %d line %d", i, k))...)
			}
		}
	}
	return errs, nBoxes, nLines, d.Warnings
}

func label(b *Box) string {
	if b.El != nil {
		return b.El.Tag()
	}
	s := b.Text.String()
	if len(s) > 20 {
		s = s[:20] + "…"
	}
	return fmt.Sprintf("text %q", s)
}

func fmtR(r [4]geom.Unit) string {
	return fmt.Sprintf("[%v %v %v %v]", r[0], r[1], r[2], r[3])
}

// diffChars compares the visual x extent of every grapheme of a line with
// Chromium's (bidi documents): chars are [text, left, right] in logical
// order, white space left out. Both edges may differ by 1/64 px (glyph
// positions are floored, Chromium's edges are not).
func diffChars(tx *text.Text, ln *text.Line, x0 geom.Unit, chars []any, tol geom.Unit, where string) []string {
	var errs []string
	p := ln.Start
	for _, ch := range chars {
		c := ch.([]any)
		g := []rune(c[0].(string))
		for p < ln.End && tx.Runes(p, min(p+len(g), ln.End)) != string(g) {
			p++
		}
		if p >= ln.End {
			return append(errs, fmt.Sprintf("%s: grapheme %q not found", where, string(g)))
		}
		sp := tx.Spans(ln, p, p+len(g))
		l, r := x0+sp[0][0], x0+sp[len(sp)-1][1]
		for _, x := range sp {
			l, r = min(l, x0+x[0]), max(r, x0+x[1])
		}
		wl, wr := toUnit(c[1].(float64)), toUnit(c[2].(float64))
		if !near(l, wl, tol+1) || !near(r, wr, tol+1) {
			errs = append(errs, fmt.Sprintf("%s: %q at [%v %v], Chromium [%v %v]", where, string(g), l, r, wl, wr))
		}
		p += len(g)
	}
	return errs
}
